D({ id: 'squash', c: 'principles', ko: '스퀘시 앤 스트레치', en: 'Squash & Stretch', dur: 1.1,
  d: '착지에서 납작해지고 빠를 때는 진행 방향으로 늘어남. 부피는 유지(scaleX × scaleY ≈ 1). 왼쪽은 변형 없음.', v: ['착지 scaleY 0.75 / scaleX 1.33	공중 stretch 1.2 / 0.85', '공중 stretch 1.2 / 0.85', '변형은 2~4프레임'], s: ['klik', 'iart', 'lottie', 'cab'], kw: ['squash'],
  f(g, t) { floor(g); const p = fract(t / 1.1), h = 4 * p * (1 - p), sp = Math.abs(1 - 2 * p);
    const y = 168 - 16 - h * 112; circ(g, 90, y, 16, null, K.mute, 1.5);
    let sy = 1 + .22 * sp * sp, sx = 1 / sy; if (p < .05 || p > .95) { sy = .72; sx = 1.36; }
    xf(g, 220, 168 - 16 * sy - h * 112, sx, sy, 0, () => circ(g, 0, 0, 16, K.red)); label(g, '없음 / 있음'); } });
D({ id: 'anticipation', c: 'principles', ko: '예비 동작(안티시페이션)', en: 'Anticipation', dur: 2.4,
  d: '크게 움직이기 전에 반대 방향으로 작게 당긴다. 주동작의 10~20% 길이·량이 기준.', v: ['반대 방향 8px 전후	60~120ms', '60〜120ms', 'button: scale 0.95 → 1'], s: ['klik', 'iart', 'lottie', 'launch'], kw: ['anticipation'],
  f(g, t) { floor(g); const x = kf(t, [[0, 60], [.4, 60], [.75, 44], [1.05, 262], [2.4, 262]], E.inOut), sx = 1 - .1 * Math.sin(clamp((t - .4) / .35) * Math.PI) + .25 * Math.sin(clamp((t - .75) / .3) * Math.PI);
    xf(g, x, 150, sx, 1 / sx, 0, () => rr(g, -18, -18, 36, 36, 6, K.red)); label(g, '뒤로 빼기 → 한꺼번에 등장'); } });
D({ id: 'staging', c: 'principles', ko: '스테이징', en: 'Staging', dur: 2.6,
  d: '보여줄 것을 하나로 좁힌다. 주변을 40~60% 어둡게 하고 주인공을 0.9 → 1.0으로 확대해 앞으로 내세움.', v: ['주위 opacity 0.4	주인공 scale 0.9→1.0', '주인공 scale 0.9→1.0', '200ms'], s: ['iart', 'lottie', 'klik'], kw: ['staging'],
  f(g, t) { const k = seg(t, .4, .7, E.outExpo) - seg(t, 1.9, 2.2); for (let i = 0; i < 5; i++) { const hero = i === 2, x = 40 + i * 60; alpha(g, hero ? 1 : 1 - .6 * k, () => xf(g, x, 100, hero ? .9 + .1 * k : .9, hero ? .9 + .1 * k : .9, 0, () => rr(g, -24, -34, 48, 68, 6, hero ? K.red : K.ink))); } } });
D({ id: 'pose', c: 'principles', ko: '포즈 투 포즈 / 스트레이트 어헤드', en: 'Pose-to-pose vs Straight-ahead', dur: 3,
  d: '왼쪽: 키포즈를 정하고 사이를 이징으로 채운다(설계 가능). 오른쪽: 앞부터 순서대로 그린다(불꽃·파티클 등 예측하기 어려운 움직임에 적합).', v: ['UI·로고는 포즈 투 포즈', '파티클·액체는 straight-ahead'], s: ['iart', 'lottie', 'klik'], kw: ['pose'],
  f(g, t) { const keys = [[0, [40, 150]], [1, [110, 60]], [2, [60, 90]], [3, [40, 150]]];
    keys.forEach(([, p]) => { xf(g, p[0], p[1], 1, 1, Math.PI / 4, () => rr(g, -4, -4, 8, 8, 1, K.blue)); });
    const i = Math.floor(t) % 3, q = E.inOut(fract(t)), a = keys[i][1], b = keys[i + 1][1]; circ(g, lerp(a[0], b[0], q), lerp(a[1], b[1], q), 9, K.red);
    let px, py; g.beginPath(); for (let s = 0; s <= 60; s++) { const u = t - s * .02; px = 220 + (noise1(u * 1.3, 1) - .5) * 150; py = 100 + (noise1(u * 1.1, 2) - .5) * 120; s ? g.lineTo(px, py) : g.moveTo(px, py); } g.strokeStyle = K.grid; g.lineWidth = 2; g.stroke();
    circ(g, 220 + (noise1(t * 1.3, 1) - .5) * 150, 100 + (noise1(t * 1.1, 2) - .5) * 120, 9, K.ink); ln(g, 160, 20, 160, 180, K.grid, 1, [3, 3]); } });
D({ id: 'follow', c: 'principles', ko: '팔로우스루／오버랩', en: 'Follow-through & Overlap', dur: 2.4,
  d: '부모가 멈춰도 자식은 조금 늦게 멈춤. 그림자·제목·부제목을 40~60ms씩 어긋나 착지시킴.', v: ['자식은 부모보다 50~150ms 뒤', '어긋남은 1~3프레임'], s: ['iart', 'lottie', 'klik', 'cab'], kw: ['follow-through', 'overlap'],
  f(g, t) { const out = seg(t, 2.0, 2.3), sp = d => spring(t - .3 - d, 170, 18, 1), y = v => lerp(-60, 0, v) - out * 30;
    alpha(g, 1 - out, () => { rr(g, 90, 58 + y(sp(.05)) + 8, 140, 92, 10, K.grid); rr(g, 90, 58 + y(sp(0)), 140, 92, 10, K.card, K.ink, 1.5);
      rr(g, 104, 74 + y(sp(.06)), 90, 12, 3, K.red); rr(g, 104, 96 + y(sp(.1)), 112, 8, 3, K.mute); rr(g, 104, 112 + y(sp(.14)), 70, 8, 3, K.mute); }); } });
D({ id: 'slowinout', c: 'principles', ko: '슬로우 인/슬로우 아웃', en: 'Slow in & Slow out', dur: 2.2,
  d: '움직이기 시작과 멈출 때를 느리게 한다. 위의 linear는 기계적, 아래는 가감속으로 자연스럽게 보인다.', v: ['등장=ease-out', '퇴장=ease-in', '화면 내 이동 = ease-in-out'], s: ['iart', 'lottie', 'klik', 'cab'], kw: ['slow in'],
  f(g, t) { const p = clamp((t - .3) / 1.3); [[E.linear, 70, K.mute, 'linear'], [E.inOutCubic, 130, K.red, 'ease-in-out']].forEach(([f, y, c, n]) => { ln(g, 40, y + 20, 280, y + 20, K.grid, 1); for (let i = 0; i <= 10; i++) { const x = lerp(40, 280, f(i / 10)); ln(g, x, y + 16, x, y + 24, K.ink, 1); } circ(g, lerp(40, 280, f(p)), y, 11, c); tx(g, n, 40, y - 22, { a: 'left', size: 10, f: 'm', w: 500, c: K.mute }); }); } });
D({ id: 'arcs', c: 'principles', ko: '아크(호 궤도)', en: 'Arcs', dur: 2.2,
  d: '자연스러운 움직임은 직선이 아니라 호를 그린다. 진행 방향과 직각으로 10~20px 어긋난 중간점을 지나게 함.', v: ['중점을 10~20px 벗어나게', '던진 물건은 포물선'], s: ['iart', 'lottie', 'klik', 'cab'], kw: ['arc'],
  f(g, t) { const a = [270, 160], b = [70, 60], c = [250, 50], p = seg(t, .3, 1.5);
    ln(g, a[0], a[1], b[0], b[1], K.grid, 1.5, [4, 4]); g.beginPath(); g.moveTo(...a); g.quadraticCurveTo(...c, ...b); g.strokeStyle = K.blue; g.lineWidth = 1.5; g.setLineDash([4, 4]); g.stroke(); g.setLineDash([]);
    const q = (u, i) => (1 - u) ** 2 * a[i] + 2 * (1 - u) * u * c[i] + u * u * b[i];
    circ(g, lerp(a[0], b[0], p), lerp(a[1], b[1], p), 10, K.mute); circ(g, q(p, 0), q(p, 1), 12, K.red); } });
D({ id: 'secondary', c: 'principles', ko: '세컨더리 액션', en: 'Secondary Action', dur: 2.6,
  d: '주동작을 받쳐주는 작은 움직임. 주인공의 30~50% 양으로, 50~100ms 늦게, 다른 이징으로 움직인다.', v: ['양은 주인공의 30~50%', '50~100ms 지연'], s: ['iart', 'lottie', 'klik'], kw: ['secondary'],
  f(g, t) { const up = seg(t, .3, .9, E.outExpo) - seg(t, 2.1, 2.5), y = lerp(200, 70, up), r = seg(t, .4, 1.0, E.outBack) * Math.PI / 2 * (1 - seg(t, 2.1, 2.5));
    rr(g, 70, y, 180, 110, 12, K.card, K.ink, 1.5); xf(g, 100, y + 30, 1, 1, r, () => { ln(g, -9, 0, 9, 0, K.red, 3); ln(g, 0, -9, 0, 9, K.red, 3); });
    for (let i = 0; i < 6; i++) { const k = clamp((t - .5 - i * .06) / .5); if (k > 0 && k < 1) alpha(g, 1 - k, () => star(g, 150 + i * 16, y + 30 - k * 18, 4, 1.5, 4, K.yel)); }
    rr(g, 125, y + 24, 100, 10, 3, K.mute); } });
D({ id: 'timing-weight', c: 'principles', ko: '타이밍(무게)', en: 'Timing = Weight', dur: 2.4,
  d: '작고 가벼운 것은 빠르게, 크고 무거운 것은 느리게. 배지 150ms, 화면 가득한 패널 500ms.', v: ['소 100~250ms', '중 200~400ms', '대 400~800ms'], s: ['iart', 'lottie', 'klik'], kw: ['timing'],
  f(g, t) { const a = seg(t, .4, .55, E.outBack), b = seg(t, .4, .9, E.outExpo), out = seg(t, 2, 2.3);
    alpha(g, 1 - out, () => { rr(g, lerp(-200, 40, b), 40, 180, 120, 12, K.ink); xf(g, 270, 60, a, a, 0, () => circ(g, 0, 0, 14, K.red)); tx(g, '150ms', 270, 92, { size: 10, f: 'm', w: 500 }); tx(g, '500ms', 130, 175, { size: 10, f: 'm', w: 500 }); }); } });
D({ id: 'exaggeration', c: 'principles', ko: '과장', en: 'Exaggeration', dur: 2.4,
  d: '실제보다 10~20% 지나쳤다 돌아온다. 성공 체크는 1.15까지 부풀었다 1.0에 가라앉는다.', v: ['scale 1.15 → 1.0', 'cubic-bezier(.34,1.56,.64,1)'], s: ['iart', 'lottie', 'klik'], kw: ['exaggeration'],
  f(g, t) { const s = seg(t, .3, .8, E.outBack) * (1 - seg(t, 2.0, 2.3)), d = seg(t, .55, .9, E.outCubic);
    xf(g, 160, 100, s, s, 0, () => { circ(g, 0, 0, 40, K.red); g.beginPath(); g.moveTo(-17, 1); g.lineTo(-5, 13); g.lineTo(19, -12); g.strokeStyle = K.paper; g.lineWidth = 7; g.lineCap = 'round'; g.lineJoin = 'round'; g.setLineDash([60, 60]); g.lineDashOffset = 60 * (1 - d); g.stroke(); g.setLineDash([]); g.lineCap = 'butt'; }); } });
D({ id: 'solid', c: 'principles', ko: '솔리드 드로잉(입체감)', en: 'Solid Drawing / Depth', dur: 3,
  d: '2.5D로 기울일 때 그림자 위치와 길이도 함께 바꿔 「두께」를 낸다. rotateY 8° 정도.', v: ['rotateY ±8°', '그림자도 동시에 움직인다'], s: ['iart', 'lottie', 'klik'], kw: ['depth'],
  f(g, t) { const a = Math.sin(t / 3 * TAU) * .14, sx = Math.cos(a * 4);
    alpha(g, .9, () => xf(g, 160 - a * 120, 162, 1.1, .25, 0, () => circ(g, 0, 0, 60, K.paper)));
    g.save(); g.translate(160, 92); g.transform(sx, a * .6, 0, 1, 0, 0); rr(g, -60, -48, 120, 96, 10, K.card, K.ink, 1.5); rr(g, -44, -30, 60, 10, 3, K.red); rr(g, -44, -10, 88, 8, 3, K.mute); g.restore(); } });
D({ id: 'appeal', c: 'principles', ko: '어필(시원함)', en: 'Appeal', dur: 2,
  d: '정성스러운 토글: 손잡이는 180ms의 ease-out, 라벨 색은 40ms 늦게 따라온다. 움직임 중에만 살짝 늘어난다.', v: ['knob 180ms easeOutCubic', '색은 40ms 뒤'], s: ['iart', 'lottie'], kw: ['appeal', 'toggle'],
  f(g, t) { const on = t % 2 < 1, p = on ? seg(t % 1, .3, .48, E.outCubic) : 1 - seg(t % 1, .3, .48, E.outCubic), pc = on ? seg(t % 1, .34, .52) : 1 - seg(t % 1, .34, .52), str = Math.sin(clamp((t % 1 - .3) / .18) * Math.PI) * 8;
    rr(g, 100, 80, 120, 50, 25, pc > .5 ? K.red : K.grid); rr(g, 108 + p * 70 - (on ? str : 0), 88, 34 + str, 34, 17, K.paper);
    tx(g, pc > .5 ? 'ON' : 'OFF', 160, 152, { size: 12, f: 'm', c: pc > .5 ? K.red : K.mute }); } });
D({ id: 'cause', c: 'principles', ko: '원인과 결과의 연쇄', en: 'Cause-and-effect Chain', dur: 2.6,
  d: '동시에 일제히 움직이지 않는다. 앞 일이 다음을 일으키는 것처럼 2~6프레임씩 어긋나게 연쇄시킨다.', v: ['간격 2~6프레임', '일제 이동 금지'], s: ['klik'], kw: ['cause'],
  f(g, t) { floor(g); for (let i = 0; i < 9; i++) { const k = seg(t, .3 + i * .12, .55 + i * .12, E.inCubic) * (1 - seg(t, 2.2, 2.5)); xf(g, 40 + i * 30, 168, 1, 1, k * 1.15, () => rr(g, -4, -50, 8, 50, 2, i === 0 ? K.red : K.ink)); } } });
D({ id: 'jitter', c: 'principles', ko: '안티 로봇(흔들림)', en: 'Anti-robotic Jitter', dur: 2.4,
  d: '위: 등간격으로 너무 정돈됨. 아래: 형제 요소별로 ±1~2프레임의 시간차와 ±2~4% 크기 차(시드 고정)를 더한다.', v: ['시간 ±1~2프레임', '크기 ±2〜4%'], s: ['klik', 'cab'], kw: ['jitter', 'twinning'],
  f(g, t) { const r = rng(7), jt = [], js = []; for (let i = 0; i < 7; i++) { jt.push((r() - .5) * .09); js.push(1 + (r() - .5) * .08); }
    for (let i = 0; i < 7; i++) { const x = 50 + i * 37, a = spring(t - .3 - i * .07, 220, 20), b = spring(t - .3 - i * .07 - jt[i], 220, 20) * js[i], out = seg(t, 2, 2.3);
      alpha(g, 1 - out, () => { rr(g, x - 10, 90 - a * 40, 20, 20, 4, K.mute); rr(g, x - 10, 170 - b * 40, 20, 20, 4, K.red); }); } } });
D({ id: 'layers3', c: 'principles', ko: '주인공·조연·배경의 3레이어', en: 'Primary / Secondary / Ambient', dur: 3,
  d: '주인공은 크게 움직이고 조연은 반응해 작고 늦게, 배경은 계속 천천히 떠다닌다. 동시에 움직이는 것은 2~3개까지.', v: ['주인공 100%', '조연 30~50%·지연', '배경 천천히 상시'], s: ['iart', 'lottie', 'klik'], kw: ['primary', 'ambient'],
  f(g, t) { for (let i = 0; i < 14; i++) { const x = (hash(i) * 340 + t * 8 * (1 + hash(i + 3))) % 340 - 10, y = 20 + hash(i + 9) * 160; circ(g, x, y, 2, K.grid); }
    const p = kf(t, [[0, 0], [.4, 0], [1, 1], [1.8, 1], [2.4, 0], [3, 0]], E.outExpo), q = kf(t, [[0, 0], [.55, 0], [1.1, 1], [1.95, 1], [2.5, 0], [3, 0]], E.outCubic);
    rr(g, lerp(40, 150, p), 70, 70, 70, 10, K.red); circ(g, 250, lerp(140, 110, q), 10, K.blue); } });
D({ id: 'ambient-hold', c: 'principles', ko: '멈춰 보이는 컷을 만들지 않음', en: 'No Dead Frames', dur: 4,
  d: '읽히도록 정지해 있는 동안에도 무언가 하나는 움직여 둔다(배경의 표류·호흡). 총 길이의 40~60%는 「쉼」이어도 좋다.', v: ['완전 정지 컷은 만들지 않는다', '쉼 40~60%'], s: ['klik', 'student', 'cab'], kw: ['static', 'idle'],
  f(g, t) { for (let i = 0; i < 18; i++) { const y = fract(hash(i) - t * .05 * (1 + hash(i + 2))) * 220 - 10; circ(g, 20 + hash(i + 5) * 280, y, 1.6, K.mute); }
    const b = 1 + .015 * Math.sin(t * TAU / 4 * 2); xf(g, 160, 100, b, b, 0, () => { tx(g, 'HOLD', 0, 0, { size: 40, f: 'd', w: 400 }); }); } });
D({ id: 'counter', c: 'principles', ko: '카운터 모션', en: 'Counter-motion', dur: 2.6,
  d: '주인공이 왼쪽에서 들어올 때 배경을 반대 방향으로 20~30% 속도로 움직이면 강렬해 보인다.', v: ['배경은 반대 방향 20~30%'], s: ['iart'], kw: ['counter'],
  f(g, t) { const p = seg(t, .3, 1.1, E.outExpo) - seg(t, 2.1, 2.5, E.inCubic); g.save(); g.translate(p * 40, 0); for (let i = -1; i < 8; i++) ln(g, i * 48, 30, i * 48 - 20, 170, K.grid, 2); g.restore(); rr(g, lerp(-120, 110, p), 70, 100, 60, 10, K.red); } });

D({ id: 'gaze', c: 'principles', ko: '시선 선행(눈이 먼저 도착하게)', en: 'Gaze Lead', dur: 2.8,
  d: '새 요소가 나타날 곳으로 작은 단서(점·선)를 100~200ms 먼저 보내고, 도착하는 순간 본체를 띄운다. 위는 단서가 없어 시선이 헤매고, 아래는 단서가 시선을 데려간다.', v: ['단서 100~200ms', '단서는 4~8px의 점 또는 선', '도착 순간에 본체 등장'], s: ['iart', 'klik'], kw: ['gaze', 'cue'],
  f(g, t) { const x0 = 52, x1 = 250, out = 1 - seg(t, 2.4, 2.7);
    ln(g, 24, 100, W - 24, 100, K.grid, 1, [3, 3]);
    [[62, false], [140, true]].forEach(([y, cue]) => { alpha(g, out, () => {
      const pr = Math.sin(clamp((t - .35) / .15) * Math.PI) * .08;
      xf(g, x0, y, 1 - pr, 1 - pr, 0, () => rr(g, -14, -14, 28, 28, 7, K.card, K.line, 1.2));
      const cp = cue ? seg(t, .45, .65) : 0, a = seg(t, cue ? .62 : .5, cue ? .74 : .62, E.outCubic), ex = lerp(x0, x1, cue ? seg(t, .5, .7) : seg(t, .72, .92)), read = ex >= x1 - 1;
      if (cue && cp > 0 && cp < 1) { alpha(g, .5, () => ln(g, x0 + 14, y, lerp(x0, x1, cp), y, K.red, 2)); circ(g, lerp(x0, x1, cp), y, 4, K.red); }
      xf(g, x1, y, .9 + .1 * a, .9 + .1 * a, 0, () => alpha(g, a, () => { rr(g, -28, -18, 56, 36, 8, K.card, K.line, 1.2); rr(g, -20, -9, 30, 6, 3, read ? K.red : K.mute); rr(g, -20, 3, 40, 5, 2, K.mute); }));
      if (a > .9) tx(g, '+' + (cue ? 80 : 420) + 'ms', x1, y + 30, { size: 9, f: 'm', w: 500, c: read ? K.ink : K.mute });
      circ(g, ex, y, 10, null, K.ink, 1.5); circ(g, ex, y, 2.5, K.ink); }); });
    label(g, '위: 단서 없음 / 아래: 단서 있음'); } });
D({ id: 'dialect', c: 'principles', ko: '모션 방언(한 장면 한 말투)', en: 'One Motion Dialect', dur: 3,
  d: '한 장면에서는 이징 곡선을 한 계열로 통일한다. 위는 곡선이 제각각이라 도착 박자가 어긋나 시끄럽고, 아래는 같은 곡선에 시간차만 주어 하나의 말투로 읽힌다.', v: ['씬당 이징 1계열 + 보조 1개', '토큰 3개 안팎: enter / exit / move', '예외는 의도한 강조 하나만'], s: ['iart', 'klik', 'lottie'], kw: ['dialect', 'easing token'],
  f(g, t) { const out = 1 - seg(t, 2.4, 2.7), top = [[E.linear, 'linear'], [E.outBack, 'back'], [E.inExpo, 'expo-in'], [E.bounce, 'bounce']];
    [[58, top], [138, top.map(() => [E.outExpo, 'expo-out'])]].forEach(([y, set], r) => { ln(g, 44, y + 22, 276, y + 22, K.grid, 1);
      set.forEach(([fn, name], i) => { const x = 74 + i * 57, k = seg(t, .4 + i * .08, 1.0 + i * .08, fn);
        alpha(g, out * clamp(k * 4), () => rr(g, x - 14, y - 6 + (1 - k) * 30, 28, 28, 6, r ? K.red : K.mute));
        tx(g, name, x, y + 36, { size: 8, f: 'm', w: 500, c: K.mute }); }); });
    label(g, '위: 제각각 / 아래: 한 계열'); } });
D({ id: 'memory', c: 'principles', ko: '방향 기억(나간 길로 돌아온다)', en: 'Spatial Memory', dur: 3,
  d: '화면 밖으로 나간 요소는 나간 쪽에서 다시 들어온다. 위는 반대편에서 튀어나와 요소가 어디에 있었는지 기억이 끊기고, 아래는 같은 쪽에서 돌아와 공간 지도가 유지된다.', v: ['퇴장과 복귀는 같은 축·같은 방향', '퇴장은 ease-in, 복귀는 ease-out', '도킹 위치를 시각 단서로 남긴다'], s: ['iart', 'klik'], kw: ['spatial', 'reverse'],
  f(g, t) { const out = seg(t, .5, 1.1, E.inCubic), back = seg(t, 1.8, 2.4, E.outExpo);
    [[28, -1], [106, 1]].forEach(([y, side]) => { rr(g, 40, y, 240, 60, 8, null, K.line, 1.2); rr(g, 276, y + 16, 5, 28, 2.5, K.blue);
      const dx = t < 1.8 ? out * 170 : side * (1 - back) * 170;
      clip(g, 40, y, 240, 60, () => { rr(g, 160 + dx - 35, y + 12, 70, 36, 8, K.card, K.ink, 1.5); rr(g, 160 + dx - 25, y + 22, 34, 6, 3, K.red); rr(g, 160 + dx - 25, y + 34, 46, 5, 2, K.mute); }); });
    label(g, '위: 반대편에서 / 아래: 나간 쪽에서'); } });

D({ id: 'enter-once', c: 'principles', ko: '한 번만 나타나고 정지', en: 'Enter Once, Then Still', dur: 3.2,
  d: '표지·제목처럼 읽는 화면은 처음 한 번만 짧게 나타나고, 이후에는 움직이지 않는다. 위는 광택이 계속 지나가 읽기를 방해하고, 아래는 0.45초 입장 뒤 완전히 멈춘다.', v: ['입장은 0.3~0.5초 한 번', '입장 뒤 반복 모션 없음', '읽는 동안은 정지'], s: [], kw: ['enter once', 'still'],
  f(g, t) { const out = 1 - seg(t, 2.8, 3.1); ln(g, 24, 100, W - 24, 100, K.grid, 1, [3, 3]);
    alpha(g, out, () => {
      tx(g, 'MOTION', 160, 62, { size: 30, f: 'd', c: K.mute });
      const x = lerp(70, 250, fract((t - .2) / .9)); if (t > .2) clip(g, x - 18, 36, 36, 56, () => tx(g, 'MOTION', 160, 62, { size: 30, f: 'd', c: K.ink }));
      const a = seg(t, .4, .85, E.outCubic); alpha(g, a, () => tx(g, 'MOTION', 160, 142 + (1 - a) * 10, { size: 30, f: 'd', c: K.ink })); });
    label(g, '위: 계속 번쩍임 / 아래: 한 번 입장 뒤 정지'); } });
D({ id: 'one-step', c: 'principles', ko: '한 단계에 사실 하나', en: 'One Fact per Step', dur: 3.6,
  d: '설명은 한 번에 한 가지씩 공개한다. 새 항목만 강조색으로 들어오고 앞 항목은 한 단계 물러난다. 위는 전부 한꺼번에 떠서 무엇부터 볼지 모른다.', v: ['한 단계 = 사실 1개', '현재 항목만 강조, 앞 항목은 opacity 0.55', '단계 사이 0.4~0.6초'], s: [], kw: ['step', 'reveal'],
  f(g, t) { const out = 1 - seg(t, 3.2, 3.5), cur = clamp(Math.floor((t - .5) / .5), 0, 3);
    alpha(g, out, () => { for (let i = 0; i < 4; i++) { const x = 26 + i * 74;
      alpha(g, seg(t, .5, .7), () => { rr(g, x, 34, 62, 36, 8, K.red); tx(g, String(i + 1), x + 31, 52, { size: 15, f: 'm', c: K.paper }); });
      const a = seg(t, .5 + .5 * i, .7 + .5 * i, E.outCubic), now = i === cur;
      alpha(g, a * (now ? 1 : .55), () => { rr(g, x, 110 + (1 - a) * 8, 62, 36, 8, now ? K.red : K.card, now ? null : K.mute, 1.2); tx(g, String(i + 1), x + 31, 128 + (1 - a) * 8, { size: 15, f: 'm', c: now ? K.paper : K.ink }); });
      circ(g, 160 + (i - 1.5) * 16, 176, 3.5, i <= cur && t > .5 ? K.red : K.grid); } });
    label(g, '위: 한꺼번에 / 아래: 한 단계씩'); } });

D({ id: 'default-final', c: 'principles', ko: '기본 상태가 끝 상태', en: 'Default Is the Final State', dur: 3.4,
  d: '평소 스타일은 완성된 화면으로 두고, 애니메이션은 재생할 때만 덧씌운다. 그러면 인쇄·PDF·동작 줄이기·미리보기처럼 애니메이션이 꺼진 곳에서도 완성된 화면이 나온다. 위는 기본값이 시작 상태라 꺼지면 빈 화면이 된다.', v: ['기본 스타일 = 완성 화면', '애니메이션은 활성 클래스에서만', '인쇄·동작 줄이기에서는 애니메이션 제거'], s: [], kw: ['final state', 'print', 'reduced motion'],
  f(g, t) { const off = t >= 1.7, out = 1 - seg(t, 3.1, 3.4);
    alpha(g, out, () => { ln(g, 24, 100, W - 24, 100, K.grid, 1, [3, 3]);
      [[34, false], [114, true]].forEach(([y, keep]) => { for (let i = 0; i < 3; i++) { const x = 40 + i * 90, a = off ? (keep ? 1 : 0) : seg(t, .3 + .15 * i, .6 + .15 * i, E.outCubic);
        alpha(g, a, () => rr(g, x, y + (1 - a) * 8, 70, 30, 8, keep ? K.red : K.mute)); if (off && !keep) rr(g, x, y, 70, 30, 8, null, K.grid, 1); }
        tx(g, off ? (keep ? '완성 화면' : '빈 화면') : '재생 중', 160, y + 50, { size: 10, f: 'm', w: 500, c: off ? (keep ? K.green : K.red) : K.mute }); }); });
    label(g, '위: 기본=시작 상태 / 아래: 기본=끝 상태'); } });
D({ id: 'finite-repeat', c: 'principles', ko: '반복은 유한하고 드물게', en: 'Repeat Rarely, Then Stop', dur: 3.6,
  d: '주목용 반복은 3회 안팎에서 멈추고, 켜져 있는 시간도 주기의 25% 이하로 둔다. 위는 핑이 끝없이 이어져 배경 소음이 되고, 아래는 세 번 울린 뒤 멈춘다.', v: ['핑 3회 뒤 정지', '켜진 시간은 주기의 25% 이하', '사용자가 반응하면 즉시 중단'], s: [], kw: ['finite', 'iteration', 'ping'],
  f(g, t) { const out = 1 - seg(t, 3.2, 3.5), ping = (x, y, u) => { if (u < 0 || u > 1) return; alpha(g, (1 - u) * .85, () => circ(g, x, y, 8 + u * 24, null, K.red, 2)); };
    alpha(g, out, () => { ln(g, 24, 100, W - 24, 100, K.grid, 1, [3, 3]);
      circ(g, 120, 60, 8, K.red); if (t > .3) ping(120, 60, fract((t - .3) / .75)); tx(g, '∞', 232, 60, { size: 26, f: 'd', c: K.mute });
      circ(g, 120, 146, 8, K.red); const k = Math.floor((t - .3) / .75); if (t > .3 && k < 3) ping(120, 146, fract((t - .3) / .75));
      tx(g, '×3', 232, 146, { size: 26, f: 'd', c: K.green });
      for (let i = 0; i < 3; i++) circ(g, 54 + i * 14, 174, 3.5, t > .3 && k >= i ? K.red : K.grid); });
    label(g, '위: 계속 / 아래: 3회 뒤 정지'); } });

