D({ id: 'e-custombounce', c: 'easing', ko: 'CustomBounce+스퀘시', en: 'CustomBounce with Squash', dur: 2.4,
  d: '튈 때마다 접지 순간만 납작하게. strength는 바운스마다 남는 에너지(0.7 전후).', v: ['strength 0.7', 'squash 접지로'], s: ['gsap', 'lottie'], kw: ['bounce', 'squash'],
  f(g, t) { floor(g); const p = clamp((t - .2) / 1.6), v = E.bounce(p), y = lerp(40, 152, v), near = 1 - Math.min(1, Math.abs(v - 1) * 25), sq = near * (1 - p) * .5;
    xf(g, 160, y + 16 * (1 + sq * .0), 1 + sq, 1 - sq, 0, () => circ(g, 0, -16, 16, K.red)); } });

