D({ id: 't-size', c: 'timing', ko: '크기로 길이를 바꾼다', en: 'Duration by Size', dur: 2.4,
  d: '마이크로 100~200ms, 패널·모달 200~400ms, 전화면·히어로 400~800ms. 같은 길이로 하면 큰 것이 가볍게 보인다.', v: ['토글 150ms	모달 350ms', '모달 350ms', '히어로 700ms'], s: ['iart', 'lottie', 'klik'], kw: ['duration'],
  f(g, t) { [[.15, 14, 50], [.35, 30, 140], [.7, 54, 250]].forEach(([d, r, x]) => { const p = seg(t, .3, .3 + d, E.outExpo) * (1 - seg(t, 2, 2.2)); xf(g, x, 96, p, p, 0, () => rr(g, -r, -r, r * 2, r * 2, r * .3, K.red)); tx(g, d * 1000 + 'ms', x, 176, { size: 10, f: 'm', w: 500 }); }); } });
