    xf(g, cx + Math.cos(tq) * (r + 10), cy + Math.sin(tq) * (r + 10), 1, 1, tq, () => poly(g, [[-5, 0], [5, -6], [5, 6]], K.blue));
    for (let i = 5; i >= 1; i--) alpha(g, .16 * clamp(sp / .35), () => xf(g, cx, cy, 1, 1, A(t - i * .012), () => b02Arrow(g)));
    xf(g, cx, cy, 1, 1, a, () => b02Arrow(g));
