    tx(g, Math.round(a * 180 / Math.PI) + '°', cx - 4, 182, { size: 11, f: 'm', w: 500, a: 'right', c: t > 1.45 ? K.red : K.ink }); tx(g, '/ 720°', cx + 4, 182, { size: 11, f: 'm', w: 500, a: 'left', c: K.mute });
