    const cx = kf(t, [[0, 262], [.1, 262], [.45, 206], [.95, 206], [1.4, 114], [2.1, 114], [2.6, 262]], ease), cy = kf(t, [[0, 168], [.1, 168], [.45, 104], [2.1, 104], [2.6, 168]], ease);
