    [[.52, 206], [1.62, 114]].forEach(([t0, px]) => { const k = seg(t, t0, t0 + .35, E.outCubic); if (t > t0 && t < t0 + .35) alpha(g, 1 - k, () => circ(g, px, 104, 4 + k * 16, null, K.blue, 1.5)); });
