    const pr = 1 - Math.abs(deg) / 180, hh = 20 * (Math.abs(Math.cos(rot)) + Math.abs(Math.sin(rot))), o = seg(t, 2.0, 2.25, E.inCubic), fi = seg(t, 0, .12);
