R({ id: 'gyroscope', dur: 2.2, ease: 'sine', still: 0.7,
  v: ['rotateX 0 → 55° → 0', 'rotateY 0 → 360°', '1100ms 중심은 고정'], vEn: ['rotateX 0 → 55° → 0', 'rotateY 0 → 360°', '1100ms, center fixed'],
  f(g, t) {
    const u = seg(t, .3, 1.4, E.linear), b = seg(t, .3, 1.4, E.sine) * TAU, ax = (u < .5 ? E.sine(u * 2) : E.sine(2 - u * 2)) * 55 * Math.PI / 180, cy = 92;
    const P = (x, y, z) => { const x1 = x * Math.cos(b) + z * Math.sin(b), z1 = -x * Math.sin(b) + z * Math.cos(b), y2 = y * Math.cos(ax) - z1 * Math.sin(ax), z2 = y * Math.sin(ax) + z1 * Math.cos(ax); return [x1, y2, z2]; };
    const ring = (fn, n = 56) => { const out = []; for (let i = 0; i < n; i++) { const a0 = i / n * TAU, a1 = (i + 1) / n * TAU, p0 = P(...fn(a0)), p1 = P(...fn(a1)); out.push([p0, p1, (p0[2] + p1[2]) / 2]); } return out; };
    const A = ring(a => [Math.cos(a) * 58, Math.sin(a) * 58, 0]), B = ring(a => [0, Math.cos(a) * 44, Math.sin(a) * 44]);
    const segs = (list, front, col, lw) => list.forEach(([p0, p1, z]) => { if ((z <= 0) !== front) return; const q0 = b02proj(p0[0], p0[1], p0[2], 160, cy), q1 = b02proj(p1[0], p1[1], p1[2], 160, cy); alpha(g, front ? 1 : .3, () => { g.lineCap = 'round'; ln(g, q0[0], q0[1], q1[0], q1[1], col, lw); g.lineCap = 'butt'; }); });
    alpha(g, .22, () => xf(g, 160, 166, 1, .14, 0, () => circ(g, 0, 0, 46, K.ink)));
    segs(A, false, K.red, 4); segs(B, false, K.blue, 3);
    circ(g, 160, cy, 10, K.ink);
    segs(A, true, K.red, 4); segs(B, true, K.blue, 3);
    const m = P(58, 0, 0), mq = b02proj(m[0], m[1], m[2], 160, cy); if (m[2] <= 0) circ(g, mq[0], mq[1], 4.5, K.yel);
    tx(g, 'X ' + Math.round(ax * 180 / Math.PI) + '°', 112, 184, { size: 11, f: 'm', w: 500, c: K.blue }); tx(g, 'Y ' + Math.round(b * 180 / Math.PI) + '°', 208, 184, { size: 11, f: 'm', w: 500, c: K.red });
    label(g, 'X와 Y의 봉우리를 어긋나게 돌린다');
  } });

