    const hx = 92, top = 46, w = 134, h = 104, M = (uu, vv) => { const X = hx + uu * Math.cos(a), Z = -uu * Math.sin(a), s = 360 / (360 + Z); return [160 + (X - 160) * s, 100 + (top + vv - 100) * s]; };
