    b03Read(g, `Y ${y <= 0 ? '−' : '+'}${Math.abs(y).toFixed(0)}  ·  scaleY ${sy.toFixed(2)}`, 160, 160, Math.abs(y) > .5 || land > .1 ? K.ink : K.mute);
