    [[24, 60, 52, 72], [244, 60, 52, 72]].forEach(([a, b, c, d]) => { rr(g, a, b, c, d, 8, K.card, K.grid, 1); rr(g, a + 8, b + 10, c - 20, 6, 3, K.grid); });
    rr(g, x, y, w, h, r, K.card, K.grid, 1.5);
    rr(g, x + 14, y + 16, 60, 9, 3, K.ink); rr(g, x + 14, y + 32, 96, 6, 3, K.mute); rr(g, x + 14, y + 44, 80, 6, 3, K.mute);
    rr(g, x + 14, y + 62, 44, 14, 7, K.grid);
    const off = fract(t / 1) * per, L0 = per * .26;
