    circ(g, x + 30, y + 30, 14, K.grid); rr(g, x + 52, y + 22, 44, 7, 3, K.ink); rr(g, x + 52, y + 34, 30, 5, 2.5, K.mute);
    for (let i = 0; i < 5; i++) rr(g, x + 16, y + 60 + i * 12, [80, 64, 72, 50, 66][i], 5, 2.5, K.mute);
    // 모서리 브래킷
    const b = 8, m = 8;
