    clip(g, x - 6, y - 4, w + 12, h + 8, () => {
      const gr = g.createLinearGradient(0, ly - 30, 0, ly);
      gr.addColorStop(0, b03A(K.red, 0)); gr.addColorStop(1, b03A(K.red, .28));
      g.fillStyle = gr; g.fillRect(x, ly - 30, w, 30);
      b03Glow(g, 12, () => ln(g, x - 6, ly, x + w + 6, ly, K.red, 2));
    });
    b03Read(g, `Y ${Math.round(lerp(-10, 110, p))}%`, 268, 100, K.ink);
