    const pr = t > .5 && t < .6 ? 1 : 0;
    xf(g, 160, 136, 1 - pr * .05, 1 - pr * .05, 0, () => { rr(g, -80, -16, 160, 32, 8, K.grid); tx(g, '로그인', 0, 1, { size: 12, w: 700, c: K.ink }); });
    const mv = seg(t, .1, .45, E.outCubic), lv = seg(t, .9, 1.4, E.inOut);
    cursor(g, lerp(270, 196, mv) + lv * 60, lerp(190, 140, mv) + lv * 30, pr);
