R({ id: 'aurora-glow', dur: 3.0, bez: [.37, 0, .63, 1],
  v: ['2 glows ±24px', 'hue 0 → 70°', '1500ms alternate'], vEn: ['2 glows ±24px', 'hue 0 → 70°', '1500ms alternate'], still: .75,
  f(g, t) {
    const u = E.sine(ping(t, 3)), th = lerp(-1.3, 1.3, u), cx = 160, cy = 96;
    const c1 = b03Mix(K.red, K.blue, u * .8), c2 = b03Mix(K.blue, K.green, u * .8);
    g.save(); g.globalCompositeOperation = 'lighter'; g.filter = 'blur(14px)';
    alpha(g, .55, () => circ(g, cx + 24 * Math.sin(th), cy - 18 * Math.cos(th), 42, c1));
    alpha(g, .5, () => circ(g, cx - 24 * Math.sin(th), cy + 18 * Math.cos(th), 40, c2));
    g.restore();
    rr(g, cx - 36, cy - 36, 72, 72, 18, K.paper, K.line, 1.5);
    tx(g, 'A', cx, cy + 2, { size: 34, f: 'd', c: K.ink });
    // 궤도 가이드
    ln(g, cx - 24, 162, cx + 24, 162, K.grid, 1); circ(g, cx + 24 * Math.sin(th), 162, 2.5, c1); circ(g, cx - 24 * Math.sin(th), 162, 2.5, c2);
    b03Read(g, `hue ${Math.round(u * 70)}°`, 160, 178);
    label(g, '빛은 바깥쪽만 도는다');
  } });

R({ id: 'radial-flash', dur: 2.0, ease: 'outExpo',
  v: ['core 100 → 220 → 100', 'ring 20 → 230 · 90 → 0%', '560ms'], vEn: ['core 100 → 220 → 100', 'ring 20 → 230 · 90 → 0%', '560ms'], still: .5,
  f(g, t) {
    const t0 = .4, core = b03Bump(t, t0, t0 + .32) ** .7, ring = seg(t, t0 + .06, t0 + .56, E.outExpo), pop = t > t0 ? 1 + .14 * Math.exp(-(t - t0) * 7) * Math.sin(Math.min((t - t0) * 22, Math.PI)) : 1;
    const cx = 160, cy = 92;
    if (t > t0 + .06 && ring < 1) alpha(g, .9 * (1 - ring), () => circ(g, cx, cy, lerp(.2, 2.3, ring) * 40, null, K.red, 3 * (1 - ring) + 1));
    if (t > t0 && t < t0 + .4) { const r = seg(t, t0, t0 + .35, E.outExpo); for (let i = 0; i < 12; i++) { const a = i / 12 * TAU + .13, d0 = 30 + r * 30, d1 = 36 + r * 52; alpha(g, 1 - r, () => ln(g, cx + Math.cos(a) * d0, cy + Math.sin(a) * d0, cx + Math.cos(a) * d1, cy + Math.sin(a) * d1, i % 2 ? K.yel : K.red, 2)); } }
    g.save(); if (core > .01) g.filter = `brightness(${1 + 1.2 * core})`;
    xf(g, cx, cy, pop, pop, 0, () => star(g, 0, 2, 30, 13, 5, K.red));
    g.restore();
    if (core > .01) { g.save(); g.globalCompositeOperation = 'lighter'; g.filter = 'blur(6px)'; alpha(g, core * .9, () => circ(g, cx, cy, 14 + core * 10, K.ink)); g.restore(); }
    b03Read(g, `brightness ${Math.round(100 + 120 * core)}`, 160, 166, core > .05 ? K.ink : K.mute);
    label(g, '중심 → 띠 순서');
  } });

R({ id: 'lens-flare-sweep', dur: 2.4, ease: 'inOut',
  v: ['source X −155 → 155', 'ghosts ×.7(2개는 역방향)', 'screen', '1050ms'], vEn: ['source X −155 → 155', 'ghosts ×.7 (2 mirrored)', 'screen', '1050ms'], still: 1.0,
  f(g, t) {
    const p = seg(t, .35, 1.4, E.inOutCubic), on = t > .35 && t < 1.4, cy = 92, dx = lerp(-155, 155, p), sx = 160 + dx;
    const peak = Math.exp(-((dx / 60) ** 2)), env = Math.sin(p * Math.PI) ** .5;
    // 축
    ln(g, 20, cy, 300, cy, K.grid, 1, [2, 4]);
    // 실루엣
    rr(g, 100, 64, 120, 56, 12, K.card, K.line, 1.5);
    tx(g, 'NOVA', 160, 93, { size: 26, f: 'd', c: K.ink });
    if (on) {
      g.save(); g.globalCompositeOperation = 'lighter';
      clip(g, 100, 64, 120, 56, () => alpha(g, .35 * peak * env, () => rr(g, 100, 64, 120, 56, 12, K.red)));
      [[.7, 10, K.red, .35], [-.7, 7, K.blue, .35], [-.4, 14, K.red, .2]].forEach(([m, r, c, a]) => { const gx = 160 + dx * m; alpha(g, a * env, () => { circ(g, gx, cy, r, c); circ(g, gx, cy, r + 3, null, c, 1); }); });
      g.filter = 'blur(3px)';
      alpha(g, env * (.5 + .5 * peak), () => xf(g, sx, cy, 1, .06, 0, () => circ(g, 0, 0, 70 + 40 * peak, K.red)));
      alpha(g, env, () => circ(g, sx, cy, 12 + 8 * peak, K.red));
      g.filter = 'none';
      alpha(g, env, () => circ(g, sx, cy, 4 + 3 * peak, K.ink));
      g.restore();
    }
    b03Read(g, on ? `X ${dx >= 0 ? '+' : '−'}${Math.abs(Math.round(dx))}` : 'X −155 → 155', 160, 166, on ? K.ink : K.mute);
    label(g, '광원과 반사가 같은 축');
  } });

R({ id: 'holographic-sheen', dur: 2.4, bez: [.37, 0, .63, 1],
  v: ['band −120% → 220%', 'hue-rotate 0 → 55 → 0', '배경만', '1300ms'], vEn: ['band −120% → 220%', 'hue-rotate 0 → 55 → 0', 'background only', '1300ms'], still: 1.0,
  f(g, t) {
    const p = seg(t, .3, 1.6, E.sine), on = t > .3 && t < 1.6, x = 74, y = 44, w = 172, h = 108;
    rr(g, x, y, w, h, 12, K.card, K.line, 1.5);
    if (on) {
      g.save(); rr(g, x, y, w, h, 12); g.clip(); g.globalCompositeOperation = 'lighter';
      g.filter = `hue-rotate(${55 * Math.sin(p * Math.PI)}deg)`;
      const bx = x + w * lerp(-1.2, 2.2, p) * .5 + w * .1; g.translate(bx, y + h / 2); g.rotate(.5);
      const gr = g.createLinearGradient(-26, 0, 26, 0), a = .55 * Math.sin(p * Math.PI) ** .4;
      [[0, K.red, 0], [.25, K.red, a], [.45, K.yel, a], [.62, K.green, a], [.8, K.blue, a], [1, K.blue, 0]].forEach(([o, c, aa]) => gr.addColorStop(o, b03A(c, aa)));
      g.fillStyle = gr; g.fillRect(-26, -h, 52, h * 2); g.restore();
    }
    // 내용(밴드 위에 그리므로 색은 변하지 않음)
    rr(g, x + 14, y + 16, 26, 20, 4, K.mute);
    tx(g, 'HOLO', x + w - 16, y + 26, { a: 'right', size: 12, f: 'd', c: K.ink });
    rr(g, x + 14, y + 62, 100, 8, 3, K.ink); rr(g, x + 14, y + 78, 64, 6, 3, K.mute);
    tx(g, '₩4,800', x + w - 16, y + h - 18, { a: 'right', size: 12, f: 'm', w: 600, c: K.ink });
    b03Read(g, on ? `hue ${Math.round(55 * Math.sin(p * Math.PI))}°` : 'hue 0°', 160, 172, on ? K.ink : K.mute);
    label(g, '무지개색은 배경에만');
  } });

// 모서리별 타원 반지름(비율)로 그림. CSS border-radius처럼 변의 합이 1을 넘으면 축소
function b03Blob(g, cx, cy, w, h, r, fill) {
  const [tl, tr, br, bl] = r, f = Math.min(1, 1 / Math.max(tl + tr, bl + br, tl + bl, tr + br));
  const x = cx - w / 2, y = cy - h / 2, R4 = [tl, tr, br, bl].map(v => v * f);
  g.beginPath();
  g.ellipse(x + R4[0] * w, y + R4[0] * h, R4[0] * w, R4[0] * h, 0, Math.PI, Math.PI * 1.5);
  g.ellipse(x + w - R4[1] * w, y + R4[1] * h, R4[1] * w, R4[1] * h, 0, Math.PI * 1.5, TAU);
  g.ellipse(x + w - R4[2] * w, y + h - R4[2] * h, R4[2] * w, R4[2] * h, 0, 0, Math.PI / 2);
  g.ellipse(x + R4[3] * w, y + h - R4[3] * h, R4[3] * w, R4[3] * h, 0, Math.PI / 2, Math.PI);
  g.closePath(); g.fillStyle = fill; g.fill();
}
R({ id: 'liquid-morph', dur: 2.2, ease: 'inOut',
  v: ['radius 50 → 62/38/55/45', '→ 34/66/42/58 → 50%', 'scale ±12%', '1100ms'], vEn: ['radius 50 → 62/38/55/45', '→ 34/66/42/58 → 50%', 'scale ±12%', '1100ms'], still: .65,
  f(g, t) {
    const T = [.3, .66, 1.04, 1.4], K4 = [[.5, .5, .5, .5], [.62, .38, .55, .45], [.34, .66, .42, .58], [.5, .5, .5, .5]];
    const r = [0, 1, 2, 3].map(i => kf(t, T.map((tt, j) => [tt, K4[j][i]]), E.inOutCubic));
    const sx = kf(t, [[.3, 1], [.66, 1.12], [1.04, .9], [1.4, 1]], E.inOutCubic), sy = kf(t, [[.3, 1], [.66, .9], [1.04, 1.1], [1.4, 1]], E.inOutCubic);
    const cx = 160, cy = 92, S = 92;
    circ(g, cx, cy, S / 2, null, K.grid, 1);
    b03Blob(g, cx, cy, S * sx, S * sy, r, K.red);
    alpha(g, .3, () => xf(g, cx - 16 * sx + (r[0] - .5) * 30, cy - 18 * sy, 1, .6, -.5, () => circ(g, 0, 0, 9, K.ink)));
    b03Read(g, r.map(v => Math.round(v * 100)).join(' / ') + '%', 160, 162, t > .3 && t < 1.4 ? K.ink : K.mute);
    b03Read(g, `scale ${sx.toFixed(2)} × ${sy.toFixed(2)}`, 160, 178);
    label(g, '네 모서리가 각각 움직임');
  } });

R({ id: 'ink-reveal', dur: 2.8, bez: [0, 0, 1, 1],
  v: ['4개의 원형 마스크', 'r 0 → 105px', '시작을 어긋나게 해 합류'], vEn: ['4 circle masks', 'r 0 → 105px', 'staggered starts merge'], still: 1.15,
  f(g, t) {
    const x = 60, y = 40, w = 200, h = 110, out = seg(t, 2.35, 2.65, E.inCubic);
    const dots = [[52, 72, .25], [120, 35, .5], [171, 72, .4], [96, 100, .75]].map(([a, b, s]) => [x + a / 220 * w, y + b / 120 * h, s]);
    g.setLineDash([3, 4]); rr(g, x, y, w, h, 12, null, K.grid, 1); g.setLineDash([]);
    const oc = offscreen(c => {
      c.filter = 'blur(2.5px)';
      dots.forEach(([dx, dy, st], i) => {
        const r = seg(t, st, st + 1.2, E.outCubic) * 110; if (r <= 0) return;
        c.beginPath(); for (let k = 0; k <= 48; k++) { const a = k / 48 * TAU, rr2 = r * (1 + (noise1(a * 2.2 + i * 9, i) - .5) * .28 * (1 - r / 130)); c.lineTo(dx + Math.cos(a) * rr2, dy + Math.sin(a) * rr2); }
        c.fillStyle = K.ink; c.fill();
      });
      c.filter = 'none';
      c.globalCompositeOperation = 'source-in';
      rr(c, x, y, w, h, 12, K.red);
      c.globalCompositeOperation = 'source-atop';
      c.font = `800 52px ${FONT.d}`; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillStyle = K.paper; c.fillText('INK', x + w / 2, y + h / 2 + 2);
      poly(c, [[x, y + h], [x, y + h * .8], [x + w * .3, y + h * .7], [x + w * .65, y + h * .86], [x + w, y + h * .72], [x + w, y + h]], K.blue);
    });
    alpha(g, 1 - out, () => g.drawImage(oc, 0, 0, W * 2, H * 2, 0, 0, W, H));
    dots.forEach(([dx, dy, st]) => { if (t < st + .1) alpha(g, 1 - seg(t, st, st + .1), () => circ(g, dx, dy, 3, K.red)); });
    label(g, '4점에서 번진다');
  } });

R({ id: 'mosaic-flip', dur: 3.0, bez: [0, 0, 1, 1],
  v: ['16 tiles · rotateY 0 → 180°', 'delay (row+col) × 5.2%', 'A면 / B면은 별도'], vEn: ['16 tiles · rotateY 0 → 180°', 'delay (row+col) × 5.2%', 'separate A / B faces'], still: 1.0,
  f(g, t) {
    const N = 4, cs = 26, x0 = 160 - N * cs / 2, y0 = 40, gcx = 160, gcy = y0 + N * cs / 2;
    for (let i = 0; i < N * N; i++) {
      const c = i % N, rI = Math.floor(i / N), tcx = x0 + c * cs + cs / 2, tcy = y0 + rI * cs + cs / 2;
      const d = (rI + c) * .114, fwd = seg(t, .3 + d, .3 + d + .45, E.inOutCubic), back = seg(t, 2.25 + (6 - rI - c) * .04, 2.6 + (6 - rI - c) * .04, E.inOutCubic);
      const a = (fwd - back) * Math.PI, cs2 = Math.cos(a), isA = cs2 >= 0, sx = Math.max(.02, Math.abs(cs2)), lift = 1 + .08 * Math.sin(a);
      xf(g, tcx, tcy, sx, lift, 0, () => clip(g, -cs / 2 + 1, -cs / 2 + 1, cs - 2, cs - 2, () => {
        rr(g, -cs / 2 + 1, -cs / 2 + 1, cs - 2, cs - 2, 3, isA ? K.card : K.red);
        tx(g, isA ? 'A' : 'B', gcx - tcx, gcy - tcy + 4, { size: 88, f: 'd', c: isA ? K.mute : K.paper });
      }));
    }
    const done = t > 1.45 && t < 2.25;
    tx(g, 'A', x0 - 18, gcy, { size: 11, f: 'm', w: 600, c: done ? K.grid : K.mute }); tx(g, 'B', x0 + N * cs + 18, gcy, { size: 11, f: 'm', w: 600, c: done ? K.red : K.grid });
    ln(g, x0, y0 + N * cs + 14, x0 + N * cs, y0 + N * cs + 14, K.grid, 1);
    const prog = clamp((t - .3) / 1.14) * (1 - seg(t, 2.25, 2.85));
    circ(g, x0 + N * cs * prog, y0 + N * cs + 14, 2.5, K.red);
    label(g, '왼쪽 위 → 오른쪽 아래로 뒤집힘');
  } });

R({ id: 'displacement-wave', dur: 2.6, bez: [0, 0, 1, 1],
  v: ['26 bands', 'sin(phase − t) × 16 × sin²(πt)', '양 끝에서 0', '2200ms'], vEn: ['26 bands', 'sin(phase − t) × 16 × sin²(πt)', 'zero at both ends', '2200ms'], still: 1.3,
  f(g, t) {
    const oc = offscreen(c => { c.font = `800 64px ${FONT.d}`; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillStyle = K.red; c.fillText('WAVE', 160, 96); });
    const tau = seg(t, .2, 2.4, E.linear), env = Math.sin(Math.PI * tau) ** 2, n = 26, y0 = 70, hh = 52, sh = hh / n;
    ln(g, 62, 60, 62, 132, K.grid, 1, [2, 3]); ln(g, 258, 60, 258, 132, K.grid, 1, [2, 3]);
    g.drawImage(oc, 0, 0, W * 2, y0 * 2, 0, 0, W, y0);
    g.drawImage(oc, 0, (y0 + hh) * 2, W * 2, (H - y0 - hh) * 2, 0, y0 + hh, W, H - y0 - hh);
    let mx = 0;
    for (let i = 0; i < n; i++) {
      const dx = Math.sin(i * .42 * 10 / n - tau * TAU * 2) * 16 * env; if (i === 10) mx = dx;
      g.drawImage(oc, 0, (y0 + i * sh) * 2, W * 2, sh * 2 + 1, dx, y0 + i * sh, W, sh + .5);
      if (i % 2 === 0) ln(g, 36, y0 + i * sh + sh / 2, 36 + dx * .8 + .01, y0 + i * sh + sh / 2, i === 10 ? K.red : K.mute, 1.5);
    }
    ln(g, 36, y0 - 4, 36, y0 + hh + 4, K.grid, 1);
    // 포락선
    const tl = 100, tw = 120; g.beginPath(); for (let i = 0; i <= 40; i++) g.lineTo(tl + i / 40 * tw, 172 - Math.sin(Math.PI * i / 40) ** 2 * 12); g.strokeStyle = K.grid; g.lineWidth = 1.5; g.stroke();
    if (tau > 0 && tau < 1) circ(g, tl + tau * tw, 172 - env * 12, 3, K.red);
    b03Read(g, `×${env.toFixed(2)}`, 160, 186, env > .05 ? K.ink : K.mute);
    label(g, '띠마다 시간차');
  } });

// ---- ref-b04.js ----
// ===== 모션 레퍼런스: 웹 스크롤/인터랙션/폼 상태/제스처/SVG 경로(b04)=====
// 공통: 둥근 모서리 클립·뷰포트·스크롤 손잡이·손가락·체크·부드러운 빛·그림자·추종 시뮬레이션·SVG 경로
function b04ClipRR(g, x, y, w, h, r, fn) { g.save(); rr(g, x, y, w, h, r); g.clip(); fn(); g.restore(); }
function b04View(g, x, y, w, h, fn, r = 12) { rr(g, x, y, w, h, r, K.paper, K.mute, 1.5); b04ClipRR(g, x + 1, y + 1, w - 2, h - 2, r - 1, fn); }
function b04Thumb(g, x, y, h, p, th = 30) { rr(g, x, y, 3, h, 1.5, K.grid); rr(g, x, y + clamp(p) * (h - th), 3, th, 1.5, K.mute); }
function b04Finger(g, x, y, a = 1) { if (a <= 0) return; alpha(g, a, () => { alpha(g, .22, () => circ(g, x, y, 11, K.ink)); circ(g, x, y, 11, null, K.ink, 1.5); }); }
function b04Dash(g, d, fn) { g.setLineDash(d); fn(); g.setLineDash([]); }
function b04Num(g, s, x, y, c, a, size) { tx(g, s, x, y, { size: size || 10, w: 500, f: 'm', c: c || K.ink, a: a || 'center' }); }
// 체크 기호(p = 그리기 진행 0..1)
function b04Check(g, x, y, s, p, col, lw = 3) {
  if (p <= 0) return;
  const pts = [[-.42, .02], [-.12, .32], [.44, -.3]].map(([a, b]) => [x + a * s, y + b * s]);
  const l1 = Math.hypot(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]), l2 = Math.hypot(pts[2][0] - pts[1][0], pts[2][1] - pts[1][1]), d = clamp(p) * (l1 + l2);
  g.beginPath(); g.moveTo(pts[0][0], pts[0][1]);
  if (d <= l1) g.lineTo(lerp(pts[0][0], pts[1][0], d / l1), lerp(pts[0][1], pts[1][1], d / l1));
  else { g.lineTo(pts[1][0], pts[1][1]); const u = (d - l1) / l2; g.lineTo(lerp(pts[1][0], pts[2][0], u), lerp(pts[1][1], pts[2][1], u)); }
  g.strokeStyle = col; g.lineWidth = lw; g.lineCap = 'round'; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';
}
// 중심이 짙고 바깥으로 옅어지는 빛(동심원 겹침. 중심의 불투명도 = a)
function b04Glow(g, x, y, r, col, a) { if (a <= 0) return; const n = 40, ai = 1 - Math.pow(1 - clamp(a), 1 / n); for (let i = 0; i < n; i++) alpha(g, ai, () => circ(g, x, y, r * Math.pow(1 - i / n, .8), col)); }
// 흐린 그림자(둥근 모서리를 조금씩 넓히며 겹침)
function b04Shadow(g, x, y, w, h, r, blur, a) { const n = 7, ai = 1 - Math.pow(1 - clamp(a), 1 / n); for (let i = 0; i < n; i++) { const e = blur * .5 * (i / (n - 1)); alpha(g, ai, () => rr(g, x - e, y - e, w + 2 * e, h + 2 * e, r + e, K.paper)); } }
// 목표값을 스프링으로 추적(0부터 t까지 고정 스텝으로 적분하므로 같은 t면 같은 값)
function b04Sim(t, target, k = 170, c = 26) {
  const dt = 1 / 120, n = Math.floor(Math.max(0, t) / dt); let p = target(0).slice(); const v = p.map(() => 0);
  for (let i = 0; i < n; i++) { const q = target(i * dt); for (let j = 0; j < p.length; j++) { v[j] += (k * (q[j] - p[j]) - c * v[j]) * dt; p[j] += v[j] * dt; } }
  return p;
}
// 목표값에 지수적으로 다가감(시정수 tau)
function b04Lag(t, target, tau) {
  const dt = 1 / 120, n = Math.floor(Math.max(0, t) / dt), f = 1 - Math.exp(-dt / tau); let p = target(0).slice();
  for (let i = 1; i <= n; i++) { const q = target(i * dt); for (let j = 0; j < p.length; j++) p[j] += (q[j] - p[j]) * f; }
  return p;
}
// 단조 함수 fn이 target을 넘는 시각(이분법)
function b04Inv(fn, target, a, b) { for (let i = 0; i < 30; i++) { const m = (a + b) / 2; if (fn(m) < target) a = m; else b = m; } return (a + b) / 2; }
// SVG 경로(M / L / C / S / Q의 절대 좌표)를 꺾은선으로 만들어 길이를 부여
function b04Path(d, s = 1, ox = 0, oy = 0) {
  const tok = d.match(/[MLCSQ]|-?[\d.]+/g); let i = 0, cmd = 'M', x = 0, y = 0, px = 0, py = 0; const pts = [], n = () => +tok[i++];
  while (i < tok.length) {
    if (/[MLCSQ]/.test(tok[i])) cmd = tok[i++];
    if (cmd === 'M') { x = px = n(); y = py = n(); pts.push([x, y]); cmd = 'L'; }
    else if (cmd === 'L') { x = px = n(); y = py = n(); pts.push([x, y]); }
    else if (cmd === 'C' || cmd === 'S') {
      let x1, y1; if (cmd === 'C') { x1 = n(); y1 = n(); } else { x1 = 2 * x - px; y1 = 2 * y - py; }
      const x2 = n(), y2 = n(), x3 = n(), y3 = n();
      for (let k = 1; k <= 28; k++) { const u = k / 28, a = (1 - u) ** 3, b = 3 * u * (1 - u) ** 2, c = 3 * u * u * (1 - u), e = u ** 3; pts.push([a * x + b * x1 + c * x2 + e * x3, a * y + b * y1 + c * y2 + e * y3]); }
      px = x2; py = y2; x = x3; y = y3;
    } else if (cmd === 'Q') {
      const x1 = n(), y1 = n(), x2 = n(), y2 = n();
      for (let k = 1; k <= 28; k++) { const u = k / 28, a = (1 - u) ** 2, b = 2 * u * (1 - u), e = u * u; pts.push([a * x + b * x1 + e * x2, a * y + b * y1 + e * y2]); }
      px = x1; py = y1; x = x2; y = y2;
    } else i++;
  }
  const P = pts.map(([a, b]) => [ox + a * s, oy + b * s]), Ls = [0];
  for (let k = 1; k < P.length; k++) Ls.push(Ls[k - 1] + Math.hypot(P[k][0] - P[k - 1][0], P[k][1] - P[k - 1][1]));
  return { P, L: Ls, len: Ls[Ls.length - 1] };
}
function b04At(p, f) { const d = clamp(f) * p.len; let k = 1; while (k < p.L.length - 1 && p.L[k] < d) k++; const l0 = p.L[k - 1], l1 = p.L[k], u = l1 > l0 ? (d - l0) / (l1 - l0) : 0; return [lerp(p.P[k - 1][0], p.P[k][0], u), lerp(p.P[k - 1][1], p.P[k][1], u), k]; }
// 경로의 a..b(길이 비율)만 그림
function b04Sub(g, p, a, b, col, lw, cap = 'round') {
  a = clamp(a); b = clamp(b); if (b - a < 1e-4) return;
  const s = b04At(p, a), e = b04At(p, b);
  g.beginPath(); g.moveTo(s[0], s[1]); for (let k = s[2]; k < e[2]; k++) g.lineTo(p.P[k][0], p.P[k][1]); g.lineTo(e[0], e[1]);
  g.strokeStyle = col; g.lineWidth = lw; g.lineCap = cap; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';
}
// 두 원 사이에 액체 목을 만듦(메타볼 연결)
function b04Meta(g, x1, y1, r1, x2, y2, r2, col) {
  circ(g, x1, y1, r1, col); circ(g, x2, y2, r2, col);
  const d = Math.hypot(x2 - x1, y2 - y1), v = .5, hs = 2.4, maxD = r1 + r2 * 2.5;
  if (d > maxD || d <= Math.abs(r1 - r2)) return;
  let u1 = 0, u2 = 0;
  if (d < r1 + r2) { u1 = Math.acos(clamp((r1 * r1 + d * d - r2 * r2) / (2 * r1 * d), -1, 1)); u2 = Math.acos(clamp((r2 * r2 + d * d - r1 * r1) / (2 * r2 * d), -1, 1)); }
  const ab = Math.atan2(y2 - y1, x2 - x1), ms = Math.acos(clamp((r1 - r2) / d, -1, 1));
  const a1 = ab + u1 + (ms - u1) * v, a2 = ab - u1 - (ms - u1) * v, a3 = ab + Math.PI - u2 - (Math.PI - u2 - ms) * v, a4 = ab - Math.PI + u2 + (Math.PI - u2 - ms) * v;
  const P = (cx, cy, a, r) => [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
  const p1 = P(x1, y1, a1, r1), p2 = P(x1, y1, a2, r1), p3 = P(x2, y2, a3, r2), p4 = P(x2, y2, a4, r2);
  const tr = r1 + r2, d2 = Math.min(v * hs, Math.hypot(p1[0] - p3[0], p1[1] - p3[1]) / tr) * Math.min(1, d * 2 / tr);
  const h1 = P(p1[0], p1[1], a1 - Math.PI / 2, r1 * d2), h2 = P(p2[0], p2[1], a2 + Math.PI / 2, r1 * d2), h3 = P(p3[0], p3[1], a3 + Math.PI / 2, r2 * d2), h4 = P(p4[0], p4[1], a4 - Math.PI / 2, r2 * d2);
  g.beginPath(); g.moveTo(p1[0], p1[1]); g.bezierCurveTo(h1[0], h1[1], h3[0], h3[1], p3[0], p3[1]); g.lineTo(p4[0], p4[1]); g.bezierCurveTo(h4[0], h4[1], h2[0], h2[1], p2[0], p2[1]); g.closePath(); g.fillStyle = col; g.fill();
}
// 풍경 그림(이미지 대신)
function b04Scene(g, x, y, w, h) {
  rr(g, x, y, w, h, 0, K.card);
  circ(g, x + w * .72, y + h * .32, h * .12, K.red);
  poly(g, [[x, y + h], [x, y + h * .62], [x + w * .22, y + h * .38], [x + w * .44, y + h * .6], [x + w * .62, y + h * .44], [x + w, y + h * .7], [x + w, y + h]], K.line);
  poly(g, [[x, y + h], [x, y + h * .82], [x + w * .3, y + h * .6], [x + w * .55, y + h * .84], [x + w * .8, y + h * .66], [x + w, y + h * .8], [x + w, y + h]], K.blue);
}
const b04GF = b04Path('M12 87 C42 8 70 111 107 57 S168 13 208 62', 1.4, 6, 16);
const b04Sig = [b04Path('M18 84 C39 4 67 6 52 70 C35 120 40 66 68 59', 1.4, 6, 8), b04Path('M63 62 C74 31 78 84 95 66 S115 46 125 64 S146 45 162 63', 1.4, 6, 8), b04Path('M39 95 Q108 79 199 83', 1.4, 6, 8)];

