    const off = u => { const [x, y] = cur(u), dx = x - CX, dy = y - CY; if (Math.hypot(dx, dy) > RAD) return [0, 0]; let ox = dx * .18, oy = dy * .18; const m = Math.hypot(ox, oy); if (m > 12) { ox *= 12 / m; oy *= 12 / m; } return [ox, oy]; };
    const [ox, oy] = b04Sim(t, off, 240, 22), [mx, my] = cur(t), m = Math.hypot(ox, oy), inside = Math.hypot(mx - CX, my - CY) < RAD;
