    rr(g, 40, 34, 240, 140, 14, K.card, K.grid, 1.5);
    for (let r = 0; r < 2; r++) for (let c = 0; c < 3; c++) { if (r === 0 && c === 1) continue; const x = 56 + c * 74, y = 52 + r * 62; rr(g, x, y, 60, 48, 10, K.line); rr(g, x + 10, y + 12, 30, 6, 3, K.mute); rr(g, x + 10, y + 24, 22, 5, 2.5, K.mute); }
    const X = 130 + dx, Y = 52 + dy;
    b04Dash(g, [3, 3], () => alpha(g, clamp(Lv * 2), () => rr(g, 130, 52, 60, 48, 10, null, K.mute, 1)));
    b04Shadow(g, X, Y + 2 + 10 * Lv, 60, 48, 10, 8 + 20 * Lv, .55 + .15 * Lv);
    xf(g, X + 30, Y + 24, s, s, 0, () => { rr(g, -30, -24, 60, 48, 10, K.red); rr(g, -20, -12, 30, 6, 3, K.paper); rr(g, -20, 0, 22, 5, 2.5, K.paper); });
    const held = t > .5 && t < 1.8, cq = seg(t, .1, .45, E.outCubic), co = seg(t, 1.95, 2.45, E.inOut);
    let cx = lerp(250, 166, cq), cy = lerp(186, 82, cq); if (held || t >= 1.8) { cx = 166 + dx; cy = 82 + dy; } cx = lerp(cx, 250, co); cy = lerp(cy, 186, co);
    cursor(g, cx, cy, held ? 1 : 0);
    b04Num(g, `scale ${s.toFixed(3)}`, 40, 188, Lv > .05 ? K.ink : K.mute, 'left', 9); b04Num(g, `shadow ${Math.round(8 + 20 * Lv)}px`, 280, 188, Lv > .05 ? K.ink : K.mute, 'right', 9);
