    rr(g, 110, 34, 58, 18, 9, fOn >= .5 ? K.ink : null, K.grid, 1); tx(g, 'FILTER', 139, 43.5, { size: 9, f: 'm', c: fOn >= .5 ? K.paper : K.mute });
