    const tile = (x, y, n, hl) => { rr(g, x, y, 56, 40, 6, K.card, K.line, 1); tx(g, n, x + 28, y + 20.5, { size: 13, f: 'm', w: 600 }); if (hl > 0) alpha(g, hl, () => { rr(g, x, y, 56, 40, 6, K.red); tx(g, n, x + 28, y + 20.5, { size: 13, f: 'm', w: 600, c: K.paper }); }); };
    [1, 4].forEach(i => { const [x, y] = slot(i), q1 = seg(t, .4, .62, E.inCubic), q2 = seg(t, 2.6, 2.9, E.outBack), s = t < 1.5 ? 1 - .3 * q1 : .7 + .3 * q2, a = t < 1.5 ? 1 - q1 : seg(t, 2.6, 2.75);
      alpha(g, a, () => xf(g, x + 28, y + 20, s, s, 0, () => tile(-28, -20, '0' + (i + 1), 0))); });
