    alpha(g, gk, () => { b08Ell(g, GX, GY, 15, 5, null, K.red, 2); ln(g, GX, my + 16, GX, GY - 3, K.red, 1, [3, 3]); });
    xf(g, GX, my, 1, 1, 0, () => { poly(g, [[0, -15], [11, 0], [0, 15], [-11, 0]], K.red); poly(g, [[0, -6], [5, 0], [0, 6], [-5, 0]], K.paper); });
