    let kb = 0, fl = 0;
    shots.forEach(([f, h]) => { const d = t - h; if (d >= 0 && d < .45) { kb += 7 * Math.sin(Math.min(1, d / .06) * Math.PI / 2) * (1 - seg(d, .06, .45, E.outCubic)); fl = Math.max(fl, 1 - d / .12); } });
    xf(g, TX + kb, 130, 1, 1, 0, () => { rr(g, -17, -38, 34, 76, 12, K.card, K.ink, 1.5); circ(g, 0, -8, 10, null, K.mute, 1.5); circ(g, 0, -8, 3, K.mute); if (fl > 0) alpha(g, fl * .8, () => rr(g, -17, -38, 34, 76, 12, K.ink)); });
    shots.forEach(([f, h, num, ox], i) => {
      if (t >= f && t < h) { const x = lerp(SX + 26, TX - 18, seg(t, f, h, E.linear)); alpha(g, .35, () => ln(g, Math.max(SX + 26, x - 30), BYL, x, BYL, K.yel, 2)); rr(g, x - 6, BYL - 2.5, 12, 5, 2.5, K.yel); }
      b08Burst(g, TX - 18, BYL, seg(t, h, h + .3), 7, 16, 11 + i, [K.yel, K.ink], 2);
      const d = t - h; if (d < 0 || d > 1.1) return;
      const s = d < .16 ? lerp(.3, 1.35, E.outCubic(d / .16)) : lerp(1.35, 1, seg(d, .16, .32, E.outCubic));
      alpha(g, 1 - seg(d, .7, 1.05), () => xf(g, TX + ox, 88 - 26 * E.outCubic(seg(d, 0, 1, E.linear)), s, s, 0, () => tx(g, num, 0, 0, { size: 20, f: 'd', c: K.red })));
    });
