    const bp = seg(tt, dt, dt + .45, E.outCubic); if (bp > 0 && bp < 1) alpha(g, 1 - bp, () => rr(g, CX - 32 - bp * 16, CY - 32 - bp * 16, 64 + bp * 32, 64 + bp * 32, 14 + bp * 8, null, K.blue, 2));
    alpha(g, 1 - dk, () => tx(g, '?', CX, CY + 1, { size: 28, f: 'd', c: K.mute }));
    const is = seg(tt, dt + .05, dt + .35, E.outBack) * a; if (is > 0) b08Sword(g, CX, CY, 1.3 * is, K.red);
    alpha(g, 1 - dk, () => { rr(g, CX - 30, CY + 46, 60, 20, 10, null, K.grid, 1.2); tx(g, '???', CX, CY + 56, { size: 10, f: 'm', c: K.mute }); });
    const pa = seg(tt, dt + .2, dt + .45, E.outCubic) * a;
