    xf(g, tx2, 0, 1, 1, 0, () => { b09Stripes(g, 0, 156, W, 20, -off, K.red); ln(g, 0, 152, W, 152, K.red, 1.5); });
    if (txt > 0) { const w = 260 * txt; clip(g, 160 - w / 2, 60, w, 80, () => { tx(g, 'WARNING', 160, 92, { size: 34, f: 'd', c: K.red }); tx(g, 'BOSS APPROACHING', 160, 122, { size: 11, f: 'm', w: 600, c: K.ink }); }); }
