// 8. 깊이 렌즈
function b10LensWorld(g, lw) {
  g.lineWidth = lw; g.strokeStyle = K.grid; g.beginPath();
  for (let x = 24; x <= 296; x += 16) { g.moveTo(x, 28); g.lineTo(x, 180); }
  for (let y = 28; y <= 180; y += 16) { g.moveTo(24, y); g.lineTo(296, y); }
  g.stroke();
  const r = rng(1010);
  for (let i = 0; i < 26; i++) { const x = 24 + Math.floor(r() * 17) * 16 + 8, y = 28 + Math.floor(r() * 9) * 16 + 8, k = r(); if (k < .3) circ(g, x, y, 3, K.blue); else if (k < .7) rr(g, x - 3, y - 3, 6, 6, 1, K.mute); else circ(g, x, y, 2, K.ink); }
}
