    if (sel > 0) alpha(g, sel, () => { const f2 = seg(t, T1, T1 + .4, E.outCubic); alpha(g, 1 - f2, () => circ(g, hx, hy, 6 + f2 * 26, null, K.red, 2)); rr(g, hx - 47, hy - 31, 94, 62, 10, null, K.red, 1); });
    const a = t < 2.9 ? grow : 1, b = back;
