    tx(g, 'ray', tl(T0) - 4, 186, { size: 8, f: 'm', w: 500, a: 'right', c: K.mute }); tx(g, 'select', tl(T1) + 4, 179, { size: 8, f: 'm', w: 500, a: 'left', c: K.ink });
