// ---- ref-b12.js ----
// ===== 모션 레퍼런스 b12: 키네틱 타이포그래피 =====
// 글자 중심 y(textBaseline = alphabetic용 drawChar. Pretendard의 캡하이트 ≈ 0.72em）
const b12Base = (cy, size) => cy + size * .36;
// 화살표(가이드용)
function b12Arrow(g, x1, y1, x2, y2, c, w = 1.5) { ln(g, x1, y1, x2, y2, c, w); const a = Math.atan2(y2 - y1, x2 - x1); poly(g, [[x2, y2], [x2 - Math.cos(a - .5) * 6, y2 - Math.sin(a - .5) * 6], [x2 - Math.cos(a + .5) * 6, y2 - Math.sin(a + .5) * 6]], c); }
// 손그림 선(SVG 패스를 3차 베지어 나열로 만든 것 → 등거리 폴리라인)
function b12Stroke() {
  const segs = [], P = (x, y) => [44 + (x - 35) * 1.27, 108 + (y - 80) * 1.27];
  let cur = [35, 93], prevC = null;
  const add = (c1, c2, e) => { segs.push([cur, c1, c2, e]); prevC = c2; cur = e; };
  add([55, 25], [49, 113], [67, 86]);
  [[[82, 64], [87, 86]], [[103, 50], [110, 72]], [[117, 105], [133, 85]], [[149, 61], [154, 80]], [[176, 92], [182, 69]], [[184, 103], [218, 70]]].forEach(([c2, e]) => add([2 * cur[0] - prevC[0], 2 * cur[1] - prevC[1]], c2, e));
  const pts = [];
  segs.forEach(([a, b, c, d], si) => { for (let i = si ? 1 : 0; i <= 40; i++) { const u = i / 40, v = 1 - u; pts.push(P(v * v * v * a[0] + 3 * v * v * u * b[0] + 3 * v * u * u * c[0] + u * u * u * d[0], v * v * v * a[1] + 3 * v * v * u * b[1] + 3 * v * u * u * c[1] + u * u * u * d[1])); } });
  const len = [0]; for (let i = 1; i < pts.length; i++) len.push(len[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  return { pts, len, total: len[len.length - 1] };
}
const b12Path = b12Stroke();
function b12At(d) { const { pts, len } = b12Path; let i = 1; while (i < len.length - 1 && len[i] < d) i++; const u = clamp((d - len[i - 1]) / (len[i] - len[i - 1] || 1)); return [lerp(pts[i - 1][0], pts[i][0], u), lerp(pts[i - 1][1], pts[i][1], u)]; }

