    g.font = `800 26px ${FONT.d}`; const need = 28 + 20 + ['MAKE', 'IT', 'MOVE'].reduce((a, s) => a + g.measureText(s).width, 0);
    // 줄바꿈이 일어난 시각(폭이 임계값을 넘은 순간)부터 FLIP으로 보간
    const cross = (a, b, dir) => { let lo = a, hi = b; for (let k = 0; k < 24; k++) { const m = (lo + hi) / 2, ww = lerp(wA, wB, dir > 0 ? seg(m, a, b, E.inOut) : 1 - seg(m, a, b, E.inOut)); if ((ww < need) === (dir > 0)) hi = m; else lo = m; } return hi; };
    const c1 = cross(.4, 1.1, 1), c2 = cross(2.5, 3.2, -1), k = seg(t, c1, c1 + .48, E.outCubic) - seg(t, c2, c2 + .48, E.outCubic);
    const A = b12Flow(g, wA), Bf = b12Flow(g, wB);
