// ---------- 데이터 클러스터 결합 ----------
R({ id: 'catalog-data-story-cluster-merge', dur: 4.2, ease: 'inOut', still: 2.9,
  v: ['9 + 7 = 16', '색 = 원래 소속', '호를 그리며 합류'], vEn: ['9 + 7 = 16', 'color = origin group', 'arc into merge'],
  f(g, t) {
    const cy = 92, dots = [];
    for (let i = 0; i < 9; i++) dots.push({ x: 62 + (i % 3) * 16, y: cy - 16 + Math.floor(i / 3) * 16, c: K.red, s: -1 });
    [[-8, -16], [8, -16], [-16, 0], [0, 0], [16, 0], [-8, 16], [8, 16]].forEach(([x, y]) => dots.push({ x: 246 + x, y: cy + y, c: K.blue, s: 1 }));
    label(g, '색과 총수를 유지');
    const pre = 1 - seg(t, .7, 1.0), post = seg(t, 2.0, 2.3) * (1 - seg(t, 3.3, 3.5)), back = seg(t, 3.75, 4.0);
    alpha(g, Math.max(pre, back), () => { [[78, 'A 9', K.red], [246, 'B 7', K.blue]].forEach(([x, s, c]) => { circ(g, x, cy, 32, null, K.grid, 1.5); tx(g, s, x, cy + 48, { size: 11, f: 'm', w: 700, c }); }); });
    alpha(g, post, () => { circ(g, 160, cy, 40, null, K.grid, 1.5); tx(g, '9 + 7 = 16', 160, cy + 56, { size: 11, f: 'm', w: 700 }); });
    dots.forEach((d, j) => {
      const r = 8 * Math.sqrt(j + .5), a = j * 2.39996, tx0 = 160 + Math.cos(a) * r, ty0 = cy + Math.sin(a) * r;
      const ord = d.s < 0 ? 8 - j : j - 9, go = seg(t, .9 + ord * .045, 1.65 + ord * .045, E.inOut), ret = seg(t, 3.3 + ord * .02, 3.75 + ord * .02, E.inOut), p = go * (1 - ret);
      const x = lerp(d.x, tx0, p), y = lerp(d.y, ty0, p) + Math.sin(p * Math.PI) * 14 * d.s;
      circ(g, x, y, 5, d.c);
    });
  } });

// ---------- 이벤트열 도미노 ----------
R({ id: 'catalog-data-story-event-domino', dur: 4.2, ease: 'outBack', still: 2.95,
  v: ['확정한 뒤 다음으로', '간격 0.62s', '기상 320ms'], vEn: ['next starts after resolve', 'interval 0.62s', 'rise 320ms'],
  f(g, t) {
    const xs = [58, 128, 198, 268], fy = 140, w = 50, h = 56, names = ['IN', 'RUN', 'SAVE', 'OUT'];
    label(g, '앞단이 확정 → 다음 단');
    floor(g, fy);
    xs.forEach((x, i) => {
      const ts = .35 + i * .62, down = seg(t, 3.5 + (3 - i) * .05, 3.75 + (3 - i) * .05, E.inCubic);
      const up = seg(t, ts, ts + .32, E.outBack) * (1 - down), sy = lerp(.08, 1, up), res = t > ts + .4;
      if (i < 3) { const a = seg(t, ts + .42, ts + .58, E.outCubic) * (1 - down), ax = x + w / 2 + 4, bx = xs[i + 1] - w / 2 - 4; if (a > 0) { ln(g, ax, fy - 28, lerp(ax, bx, a), fy - 28, K.mute, 1.5); if (a >= 1) poly(g, [[bx, fy - 28], [bx - 5, fy - 31.5], [bx - 5, fy - 24.5]], K.mute); } }
      xf(g, x, fy, 1, sy, 0, () => {
        rr(g, -w / 2, -h, w, h, 7, up > .02 && !res ? K.red : K.card, res ? K.grid : null, 1.5);
        if (up < .05) rr(g, -w / 2, -h, w, h, 7, K.line);
        alpha(g, up, () => tx(g, names[i], 0, -h / 2 + 1, { size: 11, f: 'm', w: 700, c: res ? K.ink : K.paper }));
      });
      const ck = seg(t, ts + .4, ts + .62, E.outBack) * (1 - down);
      if (ck > 0) xf(g, x + w / 2 - 2, fy - h * sy + 2, ck, ck, 0, () => { circ(g, 0, 0, 7, K.green); g.beginPath(); g.moveTo(-3, 0); g.lineTo(-1, 2.5); g.lineTo(3.2, -2.2); g.strokeStyle = K.paper; g.lineWidth = 1.8; g.stroke(); });
      tx(g, (ts).toFixed(2) + 's', x, fy + 14, { size: 8, f: 'm', w: 500, c: t > ts && down < .5 ? K.ink : K.mute });
    });
  } });

// ---------- KPI 스포트라이트 릴레이 ----------
R({ id: 'catalog-data-story-kpi-relay', dur: 4.2, spring: [170, 24, 1], still: 1.9,
  v: ['값은 움직이지 않는다', '빛만 이동', '각 1.1s 유지'], vEn: ['values never move', 'only the light moves', 'hold 1.1s each'],
  f(g, t) {
    const cs = [72, 160, 248], names = ['VIEW', 'CLICK', 'SAVE'], vals = ['72', '128', '96'], cy = 121, cw = 74, ch = 58;
    const on = seg(t, .2, .45) * (1 - seg(t, 3.35, 3.6)), lx = track(t, [[0, 72], [1.35, 160], [2.45, 248], [3.6, 72]], 170, 24);
    label(g, '값은 고정 / 빛만 옮김');
    ln(g, 36, 30, 284, 30, K.grid, 2);
    floor(g);
    alpha(g, on, () => {
      alpha(g, .14, () => poly(g, [[lx - 5, 36], [lx + 5, 36], [lx + 50, 168], [lx - 50, 168]], K.red));
      alpha(g, .3, () => xf(g, lx, 168, 1, .16, 0, () => circ(g, 0, 0, 50, K.red)));
    });
    rr(g, lx - 9, 26, 18, 10, 3, K.ink); alpha(g, on, () => rr(g, lx - 6, 34, 12, 3, 1.5, K.red));
    cs.forEach((x, i) => {
      const lit = on * clamp(1 - Math.abs(lx - x) / 56);
      alpha(g, .45 + .55 * lit, () => {
        rr(g, x - cw / 2, cy - ch / 2, cw, ch, 9, K.card, lit > .5 ? K.red : K.grid, 1.5);
        tx(g, names[i], x, cy - 14, { size: 9, f: 'm', w: 600, c: lit > .5 ? K.red : K.mute });
        tx(g, vals[i], x, cy + 8, { size: 20, f: 'm', w: 700, c: K.ink });
      });
    });
  } });

// ---------- 방사 예산 블룸 ----------
R({ id: 'catalog-data-story-budget-bloom', dur: 4.2, ease: 'inOut', still: 3.0,
  v: ['50 + 30 + 20 = 100', '호 길이 = 비율', '한 바퀴 = 100'], vEn: ['50 + 30 + 20 = 100', 'arc length = share', 'full circle = 100'],
  f(g, t) {
    const cx = 160, cy = 102, r = 50, parts = [[50, .35, 1.15, K.red], [30, 1.25, 1.75, K.blue], [20, 1.85, 2.2, K.yel]];
    const out = seg(t, 3.55, 3.9, E.inCubic), A = 1 - out;
    label(g, '호 길이 = 비율');
    circ(g, cx, cy, r, null, K.grid, 18);
    let a0 = -Math.PI / 2, tot = 0;
    alpha(g, A, () => xf(g, cx, cy, 1 - .06 * out, 1 - .06 * out, 0, () => {
      parts.forEach(([v, s, e, c]) => {
        const p = seg(t, s, e, E.inOut), a1 = a0 + v / 100 * TAU * p, am = a0 + v / 100 * Math.PI;
        if (p > 0) { g.beginPath(); g.arc(0, 0, r, a0, a1); g.strokeStyle = c; g.lineWidth = 18; g.stroke(); ln(g, Math.cos(a0) * (r - 10), Math.sin(a0) * (r - 10), Math.cos(a0) * (r + 10), Math.sin(a0) * (r + 10), K.paper, 2); }
        const k = seg(t, e - .05, e + .25, E.outBack);
        if (k > 0) xf(g, Math.cos(am) * (r + 26), Math.sin(am) * (r + 26), k, k, 0, () => tx(g, String(v), 0, 0, { size: 13, f: 'm', w: 700, c }));
        tot += v * p; a0 += v / 100 * TAU;
      });
    }));
    const pop = 1 + .12 * Math.sin(seg(t, 2.2, 2.5) * Math.PI);
    xf(g, cx, cy - 4, pop, pop, 0, () => tx(g, String(Math.round(tot * A)), 0, 0, { size: 22, f: 'm', w: 700 }));
    tx(g, '/ 100', cx, cy + 16, { size: 9, f: 'm', w: 500, c: K.mute });
  } });

// ---------- 캘린더 밀도 스윕 ----------
R({ id: 'catalog-data-story-calendar-density', dur: 4.2, ease: 'outCubic', still: 3.0,
  v: ['주별로 공개 0.42s', '진한 정도 = 건수', '날짜 배치는 고정'], vEn: ['reveal per week 0.42s', 'intensity = count', 'date layout fixed'],
  f(g, t) {
    const pc = 33, cw = 30, ch = 21, x0 = 46, y0 = 50, rp = 25, start = 2, days = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
    const A = 1 - seg(t, 3.6, 3.9);
    label(g, '주 단위 공개');
    tx(g, '적', 229, 14, { a: 'right', size: 9, f: 'm', w: 500, c: K.mute }); [.15, .4, .65, .9].forEach((v, i) => { rr(g, 233 + i * 13, 9, 10, 10, 2, K.card); alpha(g, .1 + .9 * v, () => rr(g, 233 + i * 13, 9, 10, 10, 2, K.red)); }); tx(g, '많', 287, 14, { a: 'left', size: 9, f: 'm', w: 500, c: K.mute });
    days.forEach((d, c) => tx(g, d, x0 + c * pc + cw / 2, 38, { size: 9, f: 'm', w: 600, c: c > 4 ? K.mute : K.ink }));
    for (let r = 0; r < 5; r++) {
      const tr = .35 + r * .42, act = t > tr && t < tr + .42 && A > .9;
      tx(g, 'W' + (r + 1), x0 - 8, y0 + r * rp + ch / 2, { a: 'right', size: 8, f: 'm', w: 600, c: act ? K.red : K.mute });
      for (let c = 0; c < 7; c++) {
        const day = r * 7 + c - start + 1, x = x0 + c * pc, y = y0 + r * rp;
        g.setLineDash([2, 3]); rr(g, x + .5, y + .5, cw - 1, ch - 1, 4, null, K.grid, 1); g.setLineDash([]);
        if (day < 1 || day > 31) continue;
        const p = seg(t, tr + c * .015, tr + c * .015 + .35, E.outCubic) * A, v = clamp((.12 + .88 * hash(day * 3.17 + .4)) * (c > 4 ? .45 : 1));
        alpha(g, p, () => {
          const yy = y + (1 - p) * 8;
          rr(g, x, yy, cw, ch, 4, K.card); alpha(g, .1 + .9 * v, () => rr(g, x, yy, cw, ch, 4, K.red));
          tx(g, String(day), x + 4, yy + 7, { a: 'left', size: 7, f: 'm', w: 600, c: v > .55 ? K.paper : K.ink });
        });
      }
    }
  } });

// ---------- 라이브 큐 압축 ----------
R({ id: 'catalog-data-story-queue-compress', dur: 4.2, spring: [240, 24, 1], still: 2.6,
  v: ['퇴장 300ms → 좁히기', '간격 60ms', 'n = 4 → 3'], vEn: ['exit 300ms → shift', 'stagger 60ms', 'n = 4 → 3'],
  f(g, t) {
    const sx = [70, 134, 198, 262], cy = 96, w = 50, h = 44, pre = t > 3.85, A = t < 3.6 ? 1 : pre ? seg(t, 3.95, 4.15) : 1 - seg(t, 3.6, 3.85);
    label(g, '퇴장이 끝난 뒤 채움');
    sx.forEach(x => { g.setLineDash([3, 3]); rr(g, x - w / 2, cy - h / 2, w, h, 8, null, K.grid, 1); g.setLineDash([]); });
    const done = !pre && t > 1.1, pr = pre ? 0 : seg(t, .4, 1.1, E.inOut), ex = pre ? 0 : seg(t, 1.3, 1.6, E.inCubic);
    alpha(g, A, () => {
      ['02', '03', '04'].forEach((s, i) => {
        const k = pre ? 0 : spring(t - (1.65 + i * .06), 240, 24), x = lerp(sx[i + 1], sx[i], k);
        rr(g, x - w / 2, cy - h / 2, w, h, 8, K.card, K.grid, 1.5); tx(g, s, x, cy + 1, { size: 13, f: 'm', w: 700 });
      });
      alpha(g, 1 - ex, () => {
        const y = cy - ex * 40;
        rr(g, sx[0] - w / 2, y - h / 2, w, h, 8, done ? K.green : K.red); tx(g, '01', sx[0], y - 3, { size: 13, f: 'm', w: 700, c: K.paper });
        alpha(g, .35, () => rr(g, sx[0] - 16, y + 10, 32, 4, 2, K.paper)); rr(g, sx[0] - 16, y + 10, 32 * pr, 4, 2, K.paper);
      });
      tx(g, 'n = ' + (t > 1.6 && !pre ? 3 : 4), 308, 14, { a: 'right', size: 10, f: 'm', w: 600, c: K.ink });
    });
    // 순서 타임라인
    const T = s => lerp(46, 286, (s - .2) / 2.3);
    [[.4, 1.1, K.mute, '처리'], [1.3, 1.6, K.red, '퇴장'], [1.65, 2.3, K.blue, '츠메']].forEach(([a, b, c, s]) => { rr(g, T(a), 152, T(b) - T(a), 6, 3, c); tx(g, s, (T(a) + T(b)) / 2, 168, { size: 9, f: 'm', w: 600, c }); });
    alpha(g, A, () => ln(g, T(clamp(t, .2, 2.5)), 146, T(clamp(t, .2, 2.5)), 164, K.ink, 1.5));
  } });

// ---------- 감정 스펙트럼 전이 ----------
R({ id: 'catalog-data-story-sentiment-spectrum', dur: 4.2, spring: [70, 11, 1], still: 2.6,
  v: ['−0.30 → +0.60', '위치 + 부호 + 색', 'spring 70/11'], vEn: ['−0.30 → +0.60', 'position + sign + color', 'spring 70/11'],
  f(g, t) {
    const x0 = 48, x1 = 272, y = 112, X = v => lerp(x0, x1, (v + 1) / 2);
    const v = -.3 + .9 * spring(t - .45, 70, 11) - .9 * spring(t - 3.3, 160, 26), px = X(v);
    label(g, '위치 + 부호 + 색');
    const gr = g.createLinearGradient(x0, 0, x1, 0); gr.addColorStop(0, K.yel); gr.addColorStop(.5, K.grid); gr.addColorStop(1, K.red);
    rr(g, x0, y - 5, x1 - x0, 10, 5, gr);
    [-1, -.5, 0, .5, 1].forEach(k => { ln(g, X(k), y + 9, X(k), y + (k ? 13 : 16), K.mute, 1); tx(g, k === 0 ? '0' : (k > 0 ? '+' : '−') + Math.abs(k), X(k), y + 25, { size: 9, f: 'm', w: 500, c: K.mute }); });
    tx(g, '−', 32, y, { size: 18, f: 'm', w: 700, c: K.yel }); tx(g, '+', 288, y, { size: 18, f: 'm', w: 700, c: K.red });
    const gh = seg(t, .45, .7) * (1 - seg(t, 3.2, 3.4)); alpha(g, gh, () => poly(g, [[X(-.3) - 6, y - 18], [X(-.3) + 6, y - 18], [X(-.3), y - 9]], null, K.mute, 1));
    const col = v > .05 ? K.red : v < -.05 ? K.yel : K.mute;
    ln(g, px, y - 9, px, y + 7, K.ink, 2);
    poly(g, [[px - 7, y - 20], [px + 7, y - 20], [px, y - 10]], col);
    b13Tag(g, (v >= 0 ? '+' : '−') + Math.abs(v).toFixed(2), px, y - 38, col, K.paper, 48);
  } });

// ---------- 목표 예측 아크 ----------
R({ id: 'catalog-data-story-goal-projection', dur: 4.2, ease: 'inOut', still: 3.0,
  v: ['실적 = 실선 / 예측 = 파선', '목표는 고정', '예측 1.1s'], vEn: ['actual solid / projected dashed', 'goal stays fixed', 'projection 1.1s'],
  f(g, t) {
    const obs = [[40, 140], [76, 130], [112, 114], [148, 106], [176, 92]], gx = 280, gy = 46, prj = b13Quad([176, 92], [238, 86], [gx, gy]);
    const A = 1 - seg(t, 3.6, 3.95), p1 = seg(t, .3, 1.3, E.inOut), q = seg(t, 1.5, 2.6, E.inOut);
    label(g, '실적 → 예측 → 목표');
    b13Axes(g);
    // 목표(처음부터 고정)
    ln(g, 36, gy, gx - 9, gy, K.red, 1, [2, 4]);
    circ(g, gx, gy, 8, K.paper, K.red, 2); circ(g, gx, gy, 3, K.red);
    tx(g, '목표 120', gx, gy - 18, { size: 9, f: 'm', w: 700, c: K.red });
    alpha(g, A, () => {
      alpha(g, seg(t, 1.2, 1.5), () => { ln(g, 176, 34, 176, 160, K.mute, 1, [3, 3]); tx(g, '실적', 106, 172, { size: 9, f: 'm', w: 600, c: K.ink }); tx(g, '예측', 228, 172, { size: 9, f: 'm', w: 600, c: K.yel }); });
      b13Path(g, obs, p1, K.ink, 2.5);
      if (p1 >= 1) circ(g, 176, 92, 4, K.ink);
      const [hx, hy] = b13Path(g, prj, q, K.yel, 2, [5, 4]);
      if (q > 0 && q < 1) circ(g, hx, hy, 3.5, null, K.yel, 1.5);
      const r = seg(t, 2.6, 3.3, E.outCubic); if (r > 0 && r < 1) alpha(g, 1 - r, () => circ(g, gx, gy, 9 + r * 20, null, K.red, 1.5));
    });
  } });

